def valid_board(board: list[str]) -> bool:
    seen = set()
    for r, row in enumerate(board):
        for c, d in enumerate(row):
            if d == ".":
                continue
            keys = (("row", r, d), ("col", c, d), ("box", r // 3, c // 3, d))
            if any(k in seen for k in keys):
                return False
            seen.update(keys)
    return True
